-- ru 공식 계정(pinwith_ru)·예시 계정·예시 리스트 4개. 먼저 seed_lang_loader.sql을 실행해 둘 것.
select private.seed_lang_examples('ru', 'ru', $doc${"official":{"display_name":"PinWith Официальный","bio":"Списки мест, которые собирает команда PinWith."},"samples":[{"display_name":"Тестовый пользователь 1","bio":"Демо-аккаунт PinWith: показывает, как друзья вместе планируют поездку."},{"display_name":"Тестовый пользователь 2","bio":"Демо-аккаунт PinWith: показывает, как друзья вместе планируют поездку."},{"display_name":"Тестовый пользователь 3","bio":"Демо-аккаунт PinWith: показывает, как друзья вместе планируют поездку."}],"lists":[{"role":"plain","owner":"official","slug":"moskva-klassika-centr","kind":"course","title":"Москва: классика за один день","desc":"Пешая прогулка по самому сердцу столицы — от Александровского сада через Красную площадь к Зарядью. Всё рядом, удобно уложиться в полдня-день.","themes":["Москва","пешком","центр","первый раз","классика"],"sections":[{"name":"У стен Кремля","by":"official","items":[{"place_id":"ChIJtcfi1lZKtUYRXwVsbqi9oxQ","title":"Александровский сад","memo":"Начните отсюда: у Могилы Неизвестного Солдата каждый час проходит смена почётного караула — стоит подгадать время.","tags":["парк","Кремль"],"lat":55.752222,"lng":37.613611},{"place_id":"ChIJ7UcSp1FKtUYRiaCU05I068M","title":"Сапожковая площадь","memo":"Небольшая площадь у Кутафьей башни — отсюда вход в Кремль, рядом же кассы. Хорошая точка сбора, если идёте компанией.","tags":["вход в Кремль"],"lat":55.752473,"lng":37.611861}]},{"name":"Красная площадь","by":"official","items":[{"place_id":"ChIJGaSPc1pKtUYRHzFSa1B9NHw","title":"Красная площадь","memo":"Площадь иногда закрывают под мероприятия и подготовку к праздникам — проверьте новости накануне. Рано утром почти нет людей.","tags":["must see","фото"],"lat":55.75393,"lng":37.620795},{"place_id":"ChIJ8308Z1dKtUYRB_Eb5OPQRts","title":"Памятник Минину и Пожарскому","memo":"Стоит прямо перед Покровским собором — классический кадр, где в одну рамку попадают и памятник, и купола.","tags":["памятник","фото"],"lat":55.752829,"lng":37.622735},{"place_id":"ChIJBZbmYllKtUYR5TrL54oWz6Q","title":"Храм Василия Блаженного","memo":"Внутри это не один храм, а несколько церквей-приделов с узкими лестницами и галереями — закладывайте минимум час.","tags":["музей","архитектура"],"lat":55.752523,"lng":37.623087},{"place_id":"ChIJtT472VlKtUYRu5Vhvtp-ozM","title":"Средние торговые ряды","memo":"Историческое здание напротив ГУМа со стороны Варварки — красиво смотрится с площади по дороге к Зарядью.","tags":["архитектура"],"lat":55.753094,"lng":37.623693}]},{"name":"Зарядье","by":"official","items":[{"place_id":"ChIJIa7uAFhKtUYRRWeoyNDZL6U","title":"Парк «Зарядье»","memo":"Ландшафтный парк с зонами разных природных зон России. Хорошее место передохнуть после площади — много скамеек и тени.","tags":["парк","отдых"],"lat":55.751458,"lng":37.628799},{"place_id":"ChIJUXSPFvhKtUYRuMA9FZhbLjw","title":"Парящий мост","memo":"Мост-консоль над Москвой-рекой с лучшим видом на Кремль и набережные. На закате здесь особенно людно, но оно того стоит.","tags":["вид","закат"],"lat":55.749484,"lng":37.629465},{"place_id":"ChIJOUNf7vdKtUYRcXlNVANQmGQ","title":"Стеклянная кора","memo":"Огромный стеклянный купол над амфитеатром парка — внутри свой микроклимат, так что в холодный день тут уютнее.","tags":["архитектура"],"lat":55.751101,"lng":37.631353},{"place_id":"ChIJRb8qZYNLtUYRF3l5o-fD5Wc","title":"Концертный зал «Зарядье»","memo":"Если хватит сил на вечер — посмотрите афишу: академическая музыка с одной из лучших акустик в городе. Билеты лучше брать заранее.","tags":["вечер","концерт"],"lat":55.7512,"lng":37.631328}]}],"comments":[]},{"role":"creator","owner":"official","slug":"vlog-piter-belye-nochi","kind":"course","title":"[Влог] Питер в белые ночи","desc":"Маршрут из моего влога про Петербург в белые ночи: дворцы, соборы и фонтаны Петергофа. Снимала с утра до «ночи», которая так и не наступила.","themes":["Петербург","белые ночи","влог","фото","лето"],"sections":[{"name":"День 1: центр","by":"official","items":[{"place_id":"ChIJ6eLLMgsxlkYR_F1QoCoDTgc","title":"Эрмитаж","memo":"В видео на 2:10 — Дворцовая площадь пустая в 6 утра, это лучший момент для кадра. В сам музей приходите к открытию и сразу на второй этаж.","tags":["музей","раннее утро"],"lat":59.939832,"lng":30.31456},{"place_id":"ChIJSTp6hhsxlkYR6SV9tFJytR0","title":"Исаакиевский собор","memo":"Обязательно поднимитесь на колоннаду: в белые ночи она бывает открыта и вечером — панорама на крыши и Неву в мягком свете просто сказочная.","tags":["панорама","вечер"],"lat":59.933905,"lng":30.306485},{"place_id":"ChIJbVFAKwwxlkYRt1Nx6jtvZz4","title":"Спас на Крови","memo":"Самый «открыточный» ракурс — с моста через канал Грибоедова у Конюшенной площади. Внутри мозаики, снимать лучше без вспышки.","tags":["мозаики","фото"],"lat":59.9401,"lng":30.3289},{"place_id":"ChIJhWsRwA4xlkYRVVQ7duuOte0","title":"Русский музей","memo":"Тут мой любимый кадр — фасад Михайловского дворца из сквера на площади Искусств. Внутри Айвазовский и Брюллов, закладывайте пару часов.","tags":["искусство"],"lat":59.938628,"lng":30.332277}]},{"name":"День 2: Петергоф","by":"official","items":[{"place_id":"ChIJ49ke0TBHlkYR8WtAL_wvyAE","title":"Петергоф, Большой дворец","memo":"Фонтаны работают в тёплый сезон — в видео на 7:45 видно, как их включают утром под музыку, приезжайте к этому моменту. Добираться удобно на «Метеоре» по заливу.","tags":["фонтаны","загород"],"lat":59.886304,"lng":29.908598},{"place_id":"ChIJ49ke0TBHlkYRqoMZ2e3FpHI","title":"Павильон Эрмитаж в Петергофе","memo":"Маленький павильон прямо на берегу залива — тихое место, где почти нет толпы. Свет на воде к вечеру идеален для таймлапса.","tags":["залив","таймлапс"],"lat":59.889064,"lng":29.903316}]}],"comments":[]},{"role":"friends","owner":"ex1","slug":"stambul-4-dnya-s-druzyami","kind":"collection","title":"Стамбул на 4 дня втроём","desc":"Каждый добавил свои места, а маршрут обсудили в комментариях. Итоговый план — в комментариях к Галатской башне.","themes":["Стамбул","с друзьями","4 дня","Турция"],"sections":[{"name":"Султанахмет — хочет Аня","by":"ex1","items":[{"place_id":"ChIJJxwBkr65yhQRrk9EN29vbiM","title":"Айя-София","memo":"Действующая мечеть — нужны закрытые плечи и колени, девушкам платок. Во время намаза туристов не пускают.","tags":["мечеть","must see"],"lat":41.008583,"lng":28.980175},{"place_id":"ChIJ4fRwZb25yhQRpHwVijb3LeU","title":"Голубая мечеть","memo":"Напротив Айя-Софии, вход бесплатный. Очередь движется быстро, обувь снимают на входе.","tags":["мечеть"],"lat":41.00541,"lng":28.976814},{"place_id":"ChIJ2XlLfO25yhQR8Hcxg0Af5V4","title":"Площадь Султанахмет","memo":"Между двумя мечетями — удобно встретиться здесь и взять симит у уличного продавца.","tags":["площадь"],"lat":41.006329,"lng":28.975705},{"place_id":"ChIJGfxyyJm5yhQRwZ1k9Z0lPuM","title":"Малая Айя-София","memo":"В десяти минутах пешком, но туристов в разы меньше. Тихий дворик с чайной.","tags":["тихо","мечеть"],"lat":41.002896,"lng":28.972129}]},{"name":"Базары и Галата — хочет Макс","by":"ex2","items":[{"place_id":"ChIJJwXXYpG5yhQRq5jBWgtoyGQ","title":"Гранд-базар","memo":"Торгуйтесь обязательно и спокойно. В воскресенье базар закрыт.","tags":["шопинг","торг"],"lat":41.010685,"lng":28.968068},{"place_id":"ChIJE5G_T4-5yhQRcRruEEvEG3I","title":"Площадь Беязыт","memo":"Рядом с одним из входов в базар и университетом — отсюда удобно идти вниз к Галатскому мосту.","tags":["площадь"],"lat":41.010055,"lng":28.964154},{"place_id":"ChIJG4dgweu5yhQRoGk4YDz4AJU","title":"Галатский мост","memo":"На верхнем ярусе рыбаки, на нижнем — рыбные кафе. На закате вид на мечети Старого города.","tags":["закат","балык-экмек"],"lat":41.020016,"lng":28.97322},{"place_id":"ChIJQ3x3p-e5yhQRCzOLzD3Pdkw","title":"Галатская башня","memo":"Очередь на смотровую бывает длинной — лучше к открытию или ближе к вечеру.","tags":["панорама"],"lat":41.025569,"lng":28.974129}]},{"name":"Балат — хочет Лена","by":"ex3","items":[{"place_id":"ChIJ873LR367yhQRk66rx_Do8no","title":"Балат","memo":"Старый район на Золотом Роге: крутые улочки, кафе, антикварные лавки. Удобная обувь обязательна.","tags":["район","прогулка"],"lat":41.02921,"lng":28.949343},{"place_id":"ChIJC0lvGQC7yhQR9WUWl033YYk","title":"Цветные дома Балата","memo":"Те самые разноцветные домики для фото. Это жилые дома — снимаем вежливо и не шумим.","tags":["фото"],"lat":41.029643,"lng":28.947665}]}],"comments":[{"place_id":"ChIJJxwBkr65yhQRrk9EN29vbiM","by":"ex1","body":"Давайте Айя-Софию и Голубую мечеть в первый же день утром? Пока нет жары и толп.","replies":[{"by":"ex2","body":"Ок, только учтите пятницу — в полдень там главный намаз, туристов не пускают. Лучше не в пятницу."},{"by":"ex3","body":"Тогда день 1 — четверг, Султанахмет. Я возьму палантин на всех девочек 😄"}]},{"place_id":"ChIJJwXXYpG5yhQRq5jBWgtoyGQ","by":"ex2","body":"На базар хочу минимум полдня. Бюджет на сувениры у кого какой?","replies":[{"by":"ex1","body":"У меня небольшой, я больше посмотреть. В воскресенье он закрыт, значит ставим на субботу."}]},{"place_id":"ChIJ873LR367yhQRk66rx_Do8no","by":"ex3","body":"Балат далековато от Султанахмета. Может, доехать на такси, а обратно на пароме по Золотому Рогу?","replies":[{"by":"ex2","body":"Я бы на автобусе вдоль берега, такси в пробках может встать надолго."},{"by":"ex1","body":"Согласна. И если будет дождь, Балат переносим — по мокрым мощёным спускам не очень."}]},{"place_id":"ChIJG4dgweu5yhQRoGk4YDz4AJU","by":"ex2","body":"Балык-экмек у моста — это святое. Закат там же?","replies":[{"by":"ex3","body":"Да! После базара спускаемся к мосту как раз к закату, потом пешком наверх к Галате."}]},{"place_id":"ChIJQ3x3p-e5yhQRCzOLzD3Pdkw","by":"ex1","body":"Итак, финальный план: День 1 (чт) — Айя-София, Голубая мечеть, Малая Айя-София. День 2 (пт) — Балат и Цветные дома. День 3 (сб) — Гранд-базар → Беязыт → Галатский мост на закате → Галатская башня. День 4 — свободный, чилл и покупки перед вылетом.","replies":[{"by":"ex2","body":"Идеально. На башню попробуем вечером, если очередь адская — просто посидим в кафе рядом."},{"by":"ex3","body":"Принято 👍 Отель ищу где-то между Султанахметом и Галатой, чтобы везде пешком."}]}]},{"role":"food","owner":"official","slug":"tbilisi-khinkali-i-vino","kind":"collection","title":"Тбилиси: хинкали и вино","desc":"Хинкальные, где едят сами тбилисцы, и места, где к хинкали нальют хорошего грузинского вина.","themes":["Тбилиси","хинкали","грузинская кухня","вино","еда"],"sections":[{"name":"Хинкальные","by":"official","items":[{"place_id":"ChIJQTIw59UNREARi6DBXMy1qFQ","title":"Хинкали бар №1","memo":"Популярное место — в часы ужина бывает очередь. Хинкали едят руками, держа за «хвостик», и сначала выпивают бульон.","tags":["хинкали","популярно"],"lat":41.697862,"lng":44.802782},{"place_id":"ChIJqeE97CANREARcXbv5ytWL2g","title":"Аси Хинкали","memo":"Попробуйте классические с мясом и с грибами — заказывайте поштучно, на человека обычно хватает 5–7.","tags":["хинкали"],"lat":41.709333,"lng":44.792611},{"place_id":"ChIJvfRo4LcNREARUCwjUZxyUZU","title":"Хинкальная Клике","memo":"Простая и сытная хинкальная без лишних изысков — хороший вариант для быстрого обеда.","tags":["недорого","обед"],"lat":41.695361,"lng":44.795936},{"place_id":"ChIJO1OLn9sMREARHaCDkV-WvbI","title":"Хинкальный дом на Руставели","memo":"Удобно зайти во время прогулки по проспекту Руставели. Возьмите к хинкали аджапсандали или пхали.","tags":["Руставели","центр"],"lat":41.703779,"lng":44.790768},{"place_id":"ChIJ53TjLQ8NREARMAwaJ0uapcQ","title":"Хинкали Паб","memo":"Хинкали плюс пиво и компания — хорошее место для вечера с друзьями.","tags":["вечер","пиво"],"lat":41.689816,"lng":44.80948}]},{"name":"С вином и видом на город","by":"official","items":[{"place_id":"ChIJIck-VsQNREARm36oC2n6dGg","title":"Хинкали Коллекция","memo":"Ресторан в старом городе с большой винной картой. Попросите посоветовать квеври-вино — грузинское вино из глиняных сосудов.","tags":["вино","старый город"],"lat":41.695089,"lng":44.802533},{"place_id":"ChIJ6di2y_UNREARDXXXXwSrvSQ","title":"Сене","memo":"Современная грузинская кухня в уютной обстановке — хорошее место, чтобы попробовать не только хинкали, но и хачапури, и местное вино.","tags":["ужин","вино"],"lat":41.699616,"lng":44.803742},{"place_id":"ChIJe9Tu0zoNREAReGtMT126k_U","title":"Зодиако","memo":"Подойдёт для неспешного ужина большой компанией: закажите разных блюд на стол и делите по-грузински.","tags":["компания"],"lat":41.699222,"lng":44.798837},{"place_id":"ChIJR-gbinwNREART-mqgTuKTNs","title":"Кафе Дафна","memo":"Небольшое кафе-бар в районе улицы Атонели — после ужина зайти на бокал вина.","tags":["бар","вечер"],"lat":41.699901,"lng":44.802127}]}],"comments":[]}]}$doc$::jsonb);
